import json, sys
# Tiny synthetic editor. State: draft text being edited, saved text, status.
def retry(state, outcome):
    # Current retry behaviour: clear the draft before attempting to save.
    draft = state["draft"]
    state["draft"] = ""
    if outcome == "timeout":
        state["status"] = "timeout"
    else:
        state["saved"] = draft
        state["status"] = "saved"
    return state
def export(state):
    return {"draft": state["draft"], "exported": state["draft"]}
if __name__ == "__main__":
    cmd = sys.argv[1]
    s = {"draft": "alpha", "saved": "", "status": "editing"}
    if cmd == "retry-timeout": print(json.dumps(retry(s, "timeout")))
    elif cmd == "retry-success": print(json.dumps(retry(s, "ok")))
    elif cmd == "export": print(json.dumps(export(s)))

